const data = $input.first().json;

return [
  {
    json: {
      meeting_title: data.meeting_title || "Untitled Meeting",
      meeting_date: data.meeting_date || "Unknown",
      meeting_organizer: data.meeting_organizer || "Unknown",
      participants: data.participants || "",
      meeting_type: data.meeting_type || "General",
      transcript: data.transcript || "",
      processed_at: new Date().toISOString()
    }
  }
];

const raw = $input.first().json.output;

try {
  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error("No JSON object found");
  }

  cleaned = cleaned.substring(start, end + 1);

  const result = JSON.parse(cleaned);

  return [
    {
      json: {
        ...result,
        parse_status: "success"
      }
    }
  ];

} catch (error) {

  return [
    {
      json: {
        parse_status: "failed",
        parse_error: error.message,
        raw_output: raw
      }
    }
  ];
}

const raw = $input.first().json.output;

try {
  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error("No JSON object found");
  }

  cleaned = cleaned.substring(start, end + 1);

  const report = JSON.parse(cleaned);

  return [
    {
      json: {
        report_type:
          report.report_type || "AI Meeting Action Tracker",

        meeting:
          report.meeting || {},

        executive_summary:
          report.executive_summary || "TBD",

        action_items:
          report.action_items || [],

        unassigned_tasks:
          report.unassigned_tasks || [],

        overdue_or_at_risk_items:
          report.overdue_or_at_risk_items || [],

        confirmed_decisions:
          report.confirmed_decisions || [],

        pending_decisions:
          report.pending_decisions || [],

        blockers:
          report.blockers || [],

        dependencies:
          report.dependencies || [],

        risks:
          report.risks || [],

        follow_up_requirements:
          report.follow_up_requirements || [],

        open_questions:
          report.open_questions || [],

        recommended_next_actions:
          report.recommended_next_actions || [],

        overall_meeting_status:
          report.overall_meeting_status || "TBD",

        final_assessment:
          report.final_assessment || "TBD",

        parse_status: "success"
      }
    }
  ];

} catch (error) {

  return [
    {
      json: {
        report_type: "AI Meeting Action Tracker",

        parse_status: "failed",

        parse_error: error.message,

        raw_output: raw
      }
    }
  ];
}
